package com.minewaku.chatter.identityaccess.infrastructure.user;
import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import com.minewaku.chatter.identityaccess.user.internal.model.UserId; import com.minewaku.chatter.identityaccess.user.internal.port.UserIdGenerator;
@Component public class SnowflakeUserIdGenerator implements UserIdGenerator { private static final long EPOCH=1735689600000L; private final long worker; private long last=-1,sequence; public SnowflakeUserIdGenerator(@Value("${identity-access.snowflake.worker-id:0}") long worker){if(worker<0||worker>1023)throw new IllegalArgumentException("Snowflake worker id must be 0-1023");this.worker=worker;} public synchronized UserId nextId(){long now=System.currentTimeMillis();if(now<last)throw new IllegalStateException("Clock moved backwards");if(now==last){sequence=(sequence+1)&4095;if(sequence==0){do{now=System.currentTimeMillis();}while(now<=last);}}else sequence=0;last=now;return new UserId(((now-EPOCH)<<22)|(worker<<12)|sequence);} }